ntrol" type="number" name="duration_minutes" value="60" step="15" min="15"></div><div class="col-6"><label class="form-label">Valor mensal</label><input class="form-control" name="monthly_amount" value="0,00"></div><div class="col-6"><label class="form-label">Início</label><input class="form-control" type="date" name="start_date" value="<?=date('Y-m-d')?>" required></div><div class="col-6"><label class="form-label">Fim (opcional)</label><input class="form-control" type="date" name="end_date"></div></div><textarea class="form-control my-2" name="notes" placeholder="Observações"></textarea><button class="btn btn-primary w-100">Criar e gerar reservas</button></div></form></div>
